begin;

create schema if not exists backup;
revoke all on schema backup from anon, authenticated;
create table if not exists backup.evidence_20261108 as select * from public.evidence;
create table if not exists backup.attachments_20261108 as select * from public.attachments;
alter table public.evidence add column if not exists archived boolean not null default false;
alter table public.attachments add column if not exists orig_evidence_id uuid;
create temp table plan_rows(ord int, js text, domain text, standard text, title text) on commit drop;
select '4770ee95-c1ea-4319-a437-f4f44803cc8b', p.ord, p.domain, p.standard, p.title, array[p.js], 'لم يبدأ', 'ترحيل خطة التحسين'
from plan_rows p
where not exists (select 1 from public.evidence e where e.school_id='4770ee95-c1ea-4319-a437-f4f44803cc8b' and e.ord=p.ord and e.title=p.title);
-- البنود القديمة: أول مؤشر منطبق لكل بند
create temp table old_map on commit drop as
select o.id old_id, o.status old_status, o.note, o.due,
  (select n.id from unnest(o.indicators) with ordinality u(c,k)
     join public.evidence n on n.school_id=o.school_id and n.ord between 101 and 199 and n.indicators[1]=u.c
     order by u.k limit 1) new_id
from public.evidence o
where o.school_id='4770ee95-c1ea-4319-a437-f4f44803cc8b' and not o.archived and not (o.ord between 101 and 199);
update public.attachments a set orig_evidence_id = a.evidence_id, evidence_id = m.new_id
from old_map m where a.evidence_id = m.old_id and m.new_id is not null;
-- الحالة: أعلى حالة من البنود القديمة المنقولة، والملاحظات والتاريخ
update public.evidence n set
  status = coalesce((select m.old_status from old_map m where m.new_id=n.id
     order by array_position(array['لم يبدأ','قيد التجهيز','مكتمل','معتمد'], m.old_status) desc nulls last limit 1), n.status),
  note = coalesce(nullif((select string_agg(m.note, ' — ') from old_map m where m.new_id=n.id and coalesce(m.note,'')<>''),''), n.note),
  due = coalesce((select max(m.due) from old_map m where m.new_id=n.id), n.due)
where n.school_id='4770ee95-c1ea-4319-a437-f4f44803cc8b' and n.ord between 101 and 199;
update public.evidence o set archived = true
where o.id in (select old_id from old_map where new_id is not null)
   or (o.id in (select old_id from old_map) and not exists (select 1 from public.attachments a where a.evidence_id=o.id));
commit;
